static NoYes METRuleHasExclusion(RefRecId _ruleId)
{
    GUPPricingRuleExclusion ruleExclusion;

    select firstonly RecId from ruleExclusion
        where ruleExclusion.RuleId == _ruleId;

    return ruleExclusion.RecId ? NoYes::Yes : NoYes::No;
}

static Set METGetHashKeySetForPricingRule(GUPPricingRule _pricingRule, GUPRuleHash _ruleHash)
{
    Set hashKeySet = new Set(Types::String);
    str hashKey;
    GUPPricingRuleCondition pricingRuleCondition;
    GUPPricingAttributeLink attributeLink;
    List conditionValueList;
    GUPPricingRuleCondition ruleCondition;
    GUPPricingAttributeGroupName groupName = METHashHelper::getAttrGroupNameFromRule(_pricingRule);

    if (groupName == '')
    {
        hashKeySet.add(strLRTrim(strLwr(METHashHelper::getAllValue())));
    }
    else
    {
        while select AttributeName, RecId, Priority, PriceAttributeClassId, AttributeProviderClassId, TypeName from attributeLink
            order by attributeLink.Priority
            where attributeLink.PriceAttributeGroupName == _pricingRule.PriceAttributeGroupName
               && attributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
               && attributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup
            outer join ConditionValue from ruleCondition
            where ruleCondition.RuleId == _pricingRule.RecId
               && ruleCondition.ConditionAttribute == attributeLink.RecId
        {
            if (METHashHelper::shouldSkipEmptyAttribute(ruleCondition.ConditionValue, _pricingRule.PriceAttributeGroupName))
            {
                continue;
            }

            if (ruleCondition.ConditionValue != '')
            {
                conditionValueList = strSplit(ruleCondition.ConditionValue, ',');
                GUPIPricingAttribute priceAttribute = GUPPricingAttributeRepository::priceAttribute(
                                            attributeLink.PriceAttributeClassId,
                                            attributeLink.AttributeProviderClassId,
                                            attributeLink.AttributeName,
                                            attributeLink.TypeName);
                conditionValueList = METHashHelper::removeUnusedZeroForList(priceAttribute, conditionValueList);
                GUPRuleHash::setRulePriority(_ruleHash, attributeLink);
            }
            else
            {
                conditionValueList = new List(Types::String);
                conditionValueList.addEnd(METHashHelper::getAllValue());
            }

            RecId attrLinkRecId = METHashHelper::getRecIdFromAttrLink(attributeLink, groupName);
            if (hashKeySet.empty())
            {
                ListEnumerator conditionValueEnum = conditionValueList.getEnumerator();
                while (conditionValueEnum.moveNext())
                {
                    hashKeySet.add(strLRTrim(strLwr(int642Str(attrLinkRecId) + METHashHelper::getColonChar() + strLRTrim(conditionValueEnum.current()))));
                }
            }
            else
            {
                Set newHashKeys = new Set(Types::String);
                SetEnumerator setEnumerator = hashKeySet.getEnumerator();
                while (setEnumerator.moveNext())
                {
                    ListEnumerator conditionValueEnum = conditionValueList.getEnumerator();
                    while (conditionValueEnum.moveNext())
                    {
                        newHashKeys.add(strLRTrim(strLwr(setEnumerator.current()) + METHashHelper::getSlashChar() + strLRTrim(strLwr(int642Str(attrLinkRecId) + METHashHelper::getColonChar() + strLRTrim(conditionValueEnum.current())))));
                    }
                }

                hashKeySet = newHashKeys;
            }
        }
    }

    return hashKeySet;
}
